import numpy as np
class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by measuring the average negative log-probability per token.
        Hypothesis: Hallucinated tokens are generated with significantly lower probability 
        (higher negative log-prob) than grounded tokens, and this effect persists when 
        normalized by sequence length, mitigating the bias of the raw sum score.
        """
        # Calculate mean negative log-prob per sequence
        # sequence_logprobs: List[np.ndarray], each inner array is shape (n_i - 1,)
        means = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # Ensure we don't divide by zero if sequence length is 1 (though problem says n_i-1)
            if len(seq_logprobs) == 0:
                means.append(0.0)
            else:
                mean_nll = -np.mean(seq_logprobs)
                means.append(mean_nll)

        return np.array(means, dtype=np.float32)
# Score achieved with the function above: 71.9969

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        # "sequence_logprobs": List[np.ndarray] of length N, inner 1d array has length n_i - 1.
        # MUST return shape [N] where N = number of samples
        total_neg_logprob = np.array([-np.sum(sequence_logprobs) for sequence_logprobs in stats["sequence_logprobs"]], dtype=np.float32)
        return total_neg_logprob

# Score achieved with the function above: 74.3286

